const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={token:localStorage.getItem('compesa_token'),user:null,view:'home'};
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const api=async(path,opt={})=>{const h={'Content-Type':'application/json',...(opt.headers||{})};if(state.token)h.Authorization='Bearer '+state.token;const r=await fetch('/api'+path,{...opt,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.message||'Request failed');return d};
const toast=m=>{const t=$('#toast');t.textContent=m;t.style.display='block';clearTimeout(window._tt);window._tt=setTimeout(()=>t.style.display='none',3500)};
function togglePass(id,btn){const x=$('#'+id);x.type=x.type==='password'?'text':'password';btn.textContent=x.type==='password'?'◉':'◉̸'}
function logo(){return '/static/assets/brand.png'}
function initials(name){return (name||'C').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function footerHtml(){return `<footer class="site-footer"><span>Designed &amp; Developed by</span><a href="https://www.instagram.com/anis_sayyad01/" target="_blank" rel="noopener noreferrer" aria-label="Instagram @anis_sayyad01"><img src="/static/assets/instagram.svg" alt="Instagram"><b>@anis_sayyad01</b></a></footer>`}
async function boot(){
  const params=new URLSearchParams(location.search);
  if(params.get('reset')) return resetPage(params.get('reset'));
  if(state.token){try{state.user=await api('/auth/me');return state.user.role==='student'?studentShell():adminShell()}catch{state.token=null;localStorage.removeItem('compesa_token')}}
  publicHome();
}
function publicHome(){
 document.body.className='public'; document.title='COMPESA • Event Intelligence Platform';
 document.querySelector('#app').innerHTML=`<header class="topbar"><img class="brand-img" src="${logo()}"><nav class="top-links"><a href="#" onclick="publicHome();return false">⌂ Home</a><a href="#events" onclick="publicEvents();return false">◇ Events</a><a href="#results" onclick="publicResults();return false">🏆 Results</a><a href="#updates" onclick="publicUpdates();return false">📢 Updates</a><button class="btn ghost" onclick="authPage('student')">Student Login</button><button class="btn primary" onclick="authPage('admin')">⚙ Admin</button></nav></header><main class="public-main"><section class="hero-frame"><div class="hero-copy"><img class="hero-brand" src="${logo()}"><span class="eyebrow">✦ EVENTS & INNOVATION</span><h1>COMPESA</h1><p>A professional digital platform for computer engineering events, registrations, approvals, results, certificates and student experiences.</p><div class="hero-chip-row"><span class="hero-chip">⚡ Fast Registration</span><span class="hero-chip">🔔 Live Notifications</span><span class="hero-chip">🏆 Results</span><span class="hero-chip">📜 Certificates</span></div><div class="hero-actions"><button class="btn primary" onclick="publicEvents()">Explore Events</button><button class="btn primary" onclick="authPage('student')">Student Portal</button><button class="btn ghost" onclick="verifyPublicPage()">Verify Certificate</button></div></div></section><section id="events" style="padding-top:45px"><div class="page-head"><div><span class="pill">PUBLIC EVENTS</span><h2 style="font-family:'Plus Jakarta Sans',sans-serif;font-size:30px">Upcoming COMPESA events</h2></div></div><div id="publicEventList" class="grid3"><div class="card">Loading events…</div></div></section>${footerHtml()}</main>`;
 publicEvents();
}
async function publicEvents(){if(!$('#publicEventList'))publicHome();try{const rows=await fetch('/api/public/events').then(r=>r.json());$('#publicEventList').innerHTML=rows.map(e=>`<article class="card event-card"><div class="event-cover">${e.banner_path?eventImage(e.banner_path,'event-banner'):''}<span class="pill event-cover-pill">${esc(e.category)}</span></div><div class="event-body"><h3>${esc(e.name)}</h3><p class="muted">${esc(e.description)}</p><div class="event-meta"><span>📅 ${esc(e.date)} • ${esc(e.start_time)}–${esc(e.end_time)}</span><span>📍 ${esc(e.venue)}</span></div><button class="btn primary sm" onclick="authPage('student')">Register / Student Login</button></div></article>`).join('')||'<div class="card">No upcoming events.</div>'}catch{}}
function verifyPublicPage(){document.body.className='public';document.querySelector('#app').innerHTML=`<header class="topbar"><img class="brand-img" src="${logo()}"><button class="btn ghost" onclick="publicHome()">Back to COMPESA</button></header><main class="public-main"><div class="card" style="max-width:720px;margin:50px auto"><span class="pill">PUBLIC VERIFICATION</span><h1 style="font-family:'Plus Jakarta Sans',sans-serif">Verify Certificate</h1><p class="muted">Anyone with a COMPESA certificate ID can verify its integrity and issuance record.</p><div class="field"><label>Certificate ID</label><input id="vcid" placeholder="CERT-CMP-2026-ABC123"></div><button class="btn primary" onclick="verifyPublicCert()">VERIFY</button><div id="vco" style="margin-top:18px"></div></div>${footerHtml()}</main>`}
async function verifyPublicCert(){try{const d=await fetch('/api/certificates/verify/'+encodeURIComponent($('#vcid').value)).then(r=>r.json());$('#vco').innerHTML=d.valid?`<div class="success-box"><h2>✓ Certificate Valid</h2><p><b>${esc(d.name)}</b></p><p>${esc(d.event_name)} • ${esc(d.date||'')}</p><p class="mono">${esc(d.cert_id)}</p><p>Issued by COMPESA • Integrity hash verified</p></div>`:`<div class="danger-box"><h2>Certificate not found / invalid</h2></div>`}catch(e){toast(e.message)}}
async function publicResults(){toast('Public results are available after publication.');publicHome();setTimeout(()=>document.querySelector('#results')?.scrollIntoView(),50)}
function publicUpdates(){toast('Latest event updates appear in the student notification center.');}
function authPage(mode='student'){
 document.body.className='auth-shell';document.querySelector('#app').innerHTML=`<div class="auth-card"><img class="auth-logo" src="${logo()}"><span class="pill">${mode==='admin'?'ADMIN ACCESS':'STUDENT PORTAL'}</span><h1>${mode==='admin'?'Admin sign in':'Student sign in'}</h1><p class="muted">${mode==='admin'?'Authorized event management workspace.':'Access only your profile, events, venue, announcements and personal activity.'}</p><div class="auth-tabs"><button class="${mode==='student'?'active':''}" onclick="authPage('student')">Student</button><button class="${mode==='admin'?'active':''}" onclick="authPage('admin')">Admin</button></div><form id="loginForm"><div class="field"><label>Email / Gmail</label><input id="loginEmail" type="email" required placeholder="you@gmail.com"></div><div class="field"><label>Password</label><div class="password-wrap"><input id="loginPassword" type="password" required placeholder="Enter password"><button type="button" class="show-pass" onclick="togglePass('loginPassword',this)">◉</button></div></div><button class="btn primary" style="width:100%">Sign in</button></form><div style="display:flex;justify-content:space-between;gap:10px;margin-top:15px;flex-wrap:wrap"><button class="btn ghost sm" onclick="forgotPage()">Forgot password?</button>${mode==='student'?'<button class="btn ghost sm" onclick="registerPage()">Create student account</button>':'<button class="btn ghost sm" onclick="adminRecoverPage()">Locked out?</button>'}</div><div class="auth-security-note">🔒 Passwords are private and are never displayed on this screen.</div>${footerHtml()}</div>`;
 $('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});if(mode==='admin'&&d.user.role==='student')throw new Error('Use an admin account for Admin access');if(mode==='student'&&d.user.role!=='student')throw new Error('Use the Student portal for student accounts');state.token=d.token;state.user=d.user;localStorage.setItem('compesa_token',d.token);d.user.role==='student'?studentShell():adminShell()}catch(err){toast(err.message)}};
}
function registerPage(){
 document.body.className='auth-shell';document.querySelector('#app').innerHTML=`<div class="auth-card"><img class="auth-logo" src="${logo()}"><span class="pill">STUDENT ONBOARDING</span><h1>Create your COMPESA account</h1><p class="muted">Enter your academic details once. They will appear to admins when you register for events.</p><form id="regForm"><div class="grid2"><div class="field"><label>Full Name *</label><input id="rn" required></div><div class="field"><label>PRN / Roll No. *</label><input id="rp" required></div></div><div class="grid2"><div class="field"><label>College / Student Email *</label><input id="re" type="email" required></div><div class="field"><label>Gmail / Notification Email *</label><input id="rg" type="email" required placeholder="yourname@gmail.com"></div></div><div class="grid2"><div class="field"><label>Department / Branch *</label><input id="rd" value="Computer Engineering" required></div><div class="field"><label>Year *</label><select id="ry"><option>1st Year</option><option>2nd Year</option><option selected>3rd Year</option><option>4th Year</option></select></div></div><div class="grid2"><div class="field"><label>Division *</label><input id="rv" placeholder="A" required></div><div class="field"><label>Student Contact No. *</label><input id="rm" type="tel" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" minlength="10" placeholder="10-digit mobile number" required></div></div><div class="grid2"><div class="field"><label>Skills</label><input id="rs" placeholder="Python, React, AI/ML"></div><div class="field"><label>Interests</label><input id="ri" placeholder="Coding, Hackathon, Workshop"></div></div><div class="field"><label>Password *</label><div class="password-wrap"><input id="rpass" type="password" minlength="8" required><button type="button" class="show-pass" onclick="togglePass('rpass',this)">◉</button></div></div><button class="btn primary" style="width:100%">Create account</button></form><button class="btn ghost" style="width:100%;margin-top:10px" onclick="authPage('student')">Back to login</button>${footerHtml()}</div>`;
 $('#regForm').onsubmit=async e=>{e.preventDefault();try{await api('/auth/register',{method:'POST',body:JSON.stringify({name:rn.value,prn:rp.value,email:re.value,notification_email:rg.value,department:rd.value,year:ry.value,division:rv.value,phone:rm.value,password:rpass.value,skills:rs.value,interests:ri.value})});toast('Account created. Please sign in.');setTimeout(()=>authPage('student'),700)}catch(err){toast(err.message)}};
}
function forgotPage(){document.body.className='auth-shell';document.querySelector('#app').innerHTML=`<div class="auth-card"><img class="auth-logo" src="${logo()}"><span class="pill">ACCOUNT RECOVERY</span><h1>Forgot password?</h1><p class="muted">Enter your email or Gmail. A secure reset link will be sent to your notification email when SMTP is configured.</p><form id="fp"><div class="field"><label>Email / Gmail</label><input id="femail" type="email" required></div><button class="btn primary" style="width:100%">Send reset link</button></form><button class="btn ghost" style="width:100%;margin-top:10px" onclick="authPage('student')">Back to login</button><div id="fout" style="margin-top:15px"></div>${footerHtml()}</div>`;$('#fp').onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({email:femail.value})});$('#fout').innerHTML=`<div class="notice">${esc(d.message)}${d.development_reset_url?`<br><br><a href="${d.development_reset_url}">Open development reset link</a>`:''}</div>`}catch(err){toast(err.message)}}}
function resetPage(t){document.body.className='auth-shell';document.querySelector('#app').innerHTML=`<div class="auth-card"><img class="auth-logo" src="${logo()}"><span class="pill">SECURE RESET</span><h1>Create a new password</h1><p class="muted">Your reset link is time-limited. Passwords are stored as secure hashes and cannot be viewed later.</p><form id="resetForm"><div class="field"><label>New password</label><div class="password-wrap"><input id="newpass" type="password" minlength="8" required><button type="button" class="show-pass" onclick="togglePass('newpass',this)">◉</button></div></div><div class="field"><label>Confirm password</label><div class="password-wrap"><input id="confpass" type="password" minlength="8" required><button type="button" class="show-pass" onclick="togglePass('confpass',this)">◉</button></div></div><button class="btn primary" style="width:100%">Set new password</button></form>${footerHtml()}</div>`;$('#resetForm').onsubmit=async e=>{e.preventDefault();if(newpass.value!==confpass.value)return toast('Passwords do not match');try{await api('/auth/reset-password',{method:'POST',body:JSON.stringify({token:t,password:newpass.value})});toast('Password changed successfully');history.replaceState({},'',location.pathname);setTimeout(()=>authPage('student'),700)}catch(err){toast(err.message)}}}

function adminRecoverPage(){document.body.className='auth-shell';document.querySelector('#app').innerHTML=`<div class="auth-card"><img class="auth-logo" src="${logo()}"><span class="pill">EMERGENCY RECOVERY</span><h1>Locked out of admin?</h1><p class="muted">This resets a password using the server's recovery key instead of email — for when "Forgot password?" cannot reach you. The site owner must have set a recovery key on the server first; otherwise this will say it is not enabled.</p><form id="recForm"><div class="field"><label>Admin email</label><input id="recEmail" type="email" required></div><div class="field"><label>Recovery key</label><input id="recKey" type="password" required></div><div class="field"><label>New password</label><div class="password-wrap"><input id="recPass" type="password" minlength="8" required><button type="button" class="show-pass" onclick="togglePass('recPass',this)">◉</button></div></div><button class="btn primary" style="width:100%">Reset password</button></form><button class="btn ghost" style="width:100%;margin-top:10px" onclick="authPage('admin')">Back to login</button><div id="recout" style="margin-top:15px"></div>${footerHtml()}</div>`;$('#recForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/admin-recover-password',{method:'POST',body:JSON.stringify({email:recEmail.value,recovery_key:recKey.value,new_password:recPass.value})});$('#recout').innerHTML=`<div class="notice">${esc(d.message)} Redirecting to login…</div>`;setTimeout(()=>authPage('admin'),1200)}catch(err){toast(err.message)}}}

function baseShell(role){document.body.className='portal';document.title=`COMPESA • ${role==='student'?'Student Portal':'Admin Control Center'}`;}
function studentShell(){baseShell('student');document.querySelector('#app').innerHTML=`<div class="portal-shell"><aside class="sidebar"><div class="side-brand"><img src="${logo()}"></div><div class="side-title">STUDENT EXPERIENCE</div><div class="side-nav" id="nav"><button onclick="studentView('dashboard')">⌂ Overview</button><button onclick="studentView('events')">◇ Discover Events</button><button onclick="studentView('registrations')">✓ My Registrations</button><button onclick="studentView('pass')">▣ My COMPESA Pass</button><button onclick="studentView('certificates')">▤ Certificates</button><button onclick="studentView('points')">★ Points & Achievements</button><button onclick="studentView('notifications')">🔔 Notifications</button><button onclick="studentView('ai')">✦ AI Event Match</button><button onclick="studentView('timeline')">◌ Activity Timeline</button><button onclick="studentView('preferences')">⚙ Preferences</button><button onclick="studentView('profile')">◉ My Profile</button><button onclick="studentView('privacy')">⌁ Privacy Center</button><button onclick="logout()">↪ Sign out</button></div></aside><main class="portal-main"><header class="portal-top"><div><b>COMPESA</b><span class="muted"> / Student Portal</span></div><div class="user-mini"><div><b>${esc(state.user.name)}</b><div class="small muted">${esc(state.user.department)} • ${esc(state.user.year)} • Div ${esc(state.user.division)}</div></div><div class="avatar">${initials(state.user.name)}</div></div></header><div class="portal-content" id="content"></div>${footerHtml()}</main></div>`;studentView('dashboard')}
function adminShell(){baseShell('admin');document.querySelector('#app').innerHTML=`<div class="portal-shell"><aside class="sidebar"><div class="side-brand"><img src="${logo()}"></div><div class="side-title">ADMIN COMMAND CENTER</div><div class="side-nav" id="nav"><button onclick="adminView('dashboard')">⌂ Overview</button><button onclick="adminView('registrations')">✓ Registration Approvals</button><button onclick="adminView('students')">◉ Students</button><button onclick="adminView('events')">◇ Event Management</button><button onclick="adminView('analytics')">▥ Advanced Analytics</button><button onclick="adminView('communication')">✉ Communication Center</button><button onclick="adminView('qr')">▣ QR Attendance</button><button onclick="adminView('certificates')">▤ Certificates</button><button onclick="adminView('results')">🏆 Results</button><button onclick="adminView('venues')">⌂ Smart Venues</button><button onclick="adminView('live')">🔴 Live Event Mode</button><button onclick="adminView('ai')">✦ AI Admin Copilot</button><button onclick="adminView('reports')">▦ Reports</button><button onclick="adminView('audit')">◌ Audit Logs</button>${state.user.role==='super_admin'?'<button onclick="adminView(\'database\')">🗄 Database</button>':''}<button onclick="adminView('advanced')">🚀 Advanced Engine</button><button onclick="adminView('volunteers')">🧑‍🤝‍🧑 Volunteers</button><button onclick="adminView('payments')">₹ Payments</button><button onclick="logout()">↪ Sign out</button></div></aside><main class="portal-main"><header class="portal-top"><div><b>COMPESA</b><span class="muted"> / Admin Control Center</span></div><div class="user-mini"><span class="pill admin-badge">${esc(state.user.role.replaceAll('_',' ').toUpperCase())}</span><div class="avatar">${initials(state.user.name)}</div></div></header><div class="portal-content" id="content"></div>${footerHtml()}</main></div>`;adminView('dashboard')}
function navActive(v){$$('#nav button').forEach(b=>b.classList.toggle('active',b.textContent.toLowerCase().includes(v.replace('_',' '))))}
async function studentView(v){navActive(v);state.view=v;const c=$('#content');try{
 if(v==='dashboard'){const regs=await api('/registrations/me'), rec=await api('/ai/recommendations');c.innerHTML=`<div class="page-head"><div><span class="pill">WELCOME BACK</span><h1>${esc(state.user.name)}</h1><div class="muted">Your personalized COMPESA experience</div></div></div><div class="grid"><div class="card stat-card"><span class="stat-icon">✓</span><div class="stat-label">My Registrations</div><div class="stat-num">${regs.length}</div></div><div class="card stat-card"><span class="stat-icon">★</span><div class="stat-label">COMPESA Points</div><div class="stat-num">${state.user.points||0}</div></div><div class="card stat-card"><span class="stat-icon">📜</span><div class="stat-label">Certificates</div><div class="stat-num">${(await api('/certificates')).length}</div></div><div class="card stat-card"><span class="stat-icon">🔔</span><div class="stat-label">Notifications</div><div class="stat-num">${(await api('/notifications')).filter(x=>!x.read).length}</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><div class="page-head"><div><h2>Recommended for you</h2><span class="muted">Verified from COMPESA event data</span></div></div>${rec.slice(0,3).map(r=>recommendCard(r)).join('')||'<div class="notice">No matching events yet.</div>'}</div><div class="card"><h2>Your profile snapshot</h2><div class="profile-hero"><div class="profile-avatar">${initials(state.user.name)}</div><div><h2 style="margin:0">${esc(state.user.name)}</h2><div>${esc(state.user.prn)} • ${esc(state.user.department)}</div><div class="small" style="margin-top:6px">${esc(state.user.year)} • Division ${esc(state.user.division)}</div></div></div><div style="margin-top:15px" class="chips">${(state.user.skills||'').split(',').filter(Boolean).map(x=>`<span class="pill">${esc(x.trim())}</span>`).join('')}</div></div></div>`}
 else if(v==='events'){const rows=await api('/events');c.innerHTML=`<div class="page-head"><div><span class="pill">DISCOVER</span><h1>Events for you</h1><div class="muted">Only event information relevant to your student account is shown.</div></div></div><div class="search-row"><input id="sq" placeholder="Search events…" oninput="filterStudentEvents()"><select id="sc" onchange="filterStudentEvents()"><option value="">All categories</option>${[...new Set(rows.map(x=>x.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="studentEvents" class="grid3">${rows.map(eventCardStudent).join('')}</div>`;window._studentEvents=rows}
 else if(v==='registrations'){const rows=await api('/registrations/me');c.innerHTML=`<div class="page-head"><div><span class="pill">MY ACTIVITY</span><h1>My Registrations</h1><div class="muted">Your status, venue and personal QR access.</div></div></div><div class="grid2">${rows.map(r=>`<div class="card"><div style="display:flex;justify-content:space-between;gap:10px"><div><span class="pill">${esc(r.category)}</span><h2>${esc(r.event_name)}</h2></div><span class="status ${r.status}">${r.status}</span></div><div class="event-meta"><span>📅 ${r.date} • ${r.start_time}–${r.end_time}</span><span>📍 ${esc(r.venue)}</span><span class="mono">${esc(r.reg_code)}</span></div>${r.status==='APPROVED'?`<button class="btn primary" onclick="showQR(${r.id},'${esc(r.event_name)}','${esc(r.reg_code)}')">Open secure QR pass</button>`:'<div class="notice">Your QR becomes active after admin approval. You will also receive an email notification.</div>'}</div>`).join('')||'<div class="card">You have not registered for an event yet.</div>'}</div>`}
 else if(v==='pass'){const rows=await api('/registrations/me');const approved=rows.find(x=>x.status==='APPROVED');c.innerHTML=`<div class="page-head"><div><span class="pill">DIGITAL CAMPUS PASS</span><h1>My COMPESA Pass</h1></div></div><div class="grid2"><div class="card" style="background:linear-gradient(145deg,#06101d,#0d3352);color:#fff"><img src="${logo()}" style="width:260px;max-width:100%"><div style="display:flex;gap:18px;align-items:center;margin-top:28px"><div class="profile-avatar">${initials(state.user.name)}</div><div><h2 style="margin:0">${esc(state.user.name)}</h2><div>${esc(state.user.prn)}</div><div>${esc(state.user.department)}</div></div></div><div class="grid3" style="margin-top:22px"><div><small>Score</small><h2>${state.user.points||0} ⭐</h2></div><div><small>Events</small><h2>${rows.length}</h2></div><div><small>Certificates</small><h2>${(await api('/certificates')).length}</h2></div></div></div><div class="card qr-card">${approved?`<h2>Secure Event QR</h2><p class="muted">${esc(approved.event_name)}</p><img src="/api/qr/${approved.id}.png?access_token=${encodeURIComponent(state.token)}"><p class="small muted">QR activates only after approval and is linked to a secure registration token.</p>`:'<h2>No active QR</h2><p class="muted">Register for an event and wait for approval.</p>'}</div></div>`}
 else if(v==='certificates'){const rows=await api('/certificates');c.innerHTML=`<div class="page-head"><div><span class="pill">ACHIEVEMENTS</span><h1>My Certificates</h1></div></div><div class="grid3">${rows.map(x=>`<div class="card"><span class="status APPROVED">✓ VERIFIED RECORD</span><h3>${esc(x.event_name)}</h3><div class="mono small">${esc(x.cert_id)}</div><p class="muted">Issued ${esc(x.issued_at).slice(0,10)}</p><a class="btn primary sm" href="/api/certificates/${encodeURIComponent(x.cert_id)}/pdf" target="_blank">Open certificate</a></div>`).join('')||'<div class="card">No certificates yet.</div>'}</div>`}
 else if(v==='points'){const regs=await api('/registrations/me'),certs=await api('/certificates');c.innerHTML=`<div class="page-head"><div><span class="pill">GAMIFICATION</span><h1>My Points & Achievements</h1><div class="muted">Only your own activity data is visible in the student portal.</div></div></div><div class="grid3"><div class="card stat-card"><div class="stat-label">COMPESA Score</div><div class="stat-num">${state.user.points||0} ⭐</div></div><div class="card stat-card"><div class="stat-label">Events</div><div class="stat-num">${regs.length}</div></div><div class="card stat-card"><div class="stat-label">Certificates</div><div class="stat-num">${certs.length}</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Your achievement badges</h2><div class="grid3"><div class="notice">⚡ Event Explorer</div><div class="notice">💻 Coding Champion</div><div class="notice">⭐ COMPESA Star</div></div></div><div class="card"><h2>How your score grows</h2><p>Event Registration <b>+5</b></p><p>Event Participation <b>+10</b></p><p>Workshop <b>+15</b></p><p>Competition <b>+20</b></p><p>Winner <b>+50</b></p></div></div>`}
 else if(v==='notifications'){const rows=await api('/notifications');c.innerHTML=`<div class="page-head"><div><span class="pill">COMMUNICATION</span><h1>Notification Center</h1></div></div><div class="grid2">${rows.map(n=>`<div class="card" style="border-left:4px solid ${n.read?'#dce5f0':'#168cff'}"><div style="display:flex;justify-content:space-between"><h3>${esc(n.title)}</h3><span class="small muted">${esc(n.created_at).slice(0,16).replace('T',' ')}</span></div><p class="muted">${esc(n.body)}</p>${!n.read?`<button class="btn ghost sm" onclick="markRead(${n.id})">Mark read</button>`:''}</div>`).join('')||'<div class="card">No notifications.</div>'}</div>`}
 else if(v==='ai'){const rec=await api('/ai/recommendations');c.innerHTML=`<div class="page-head"><div><span class="pill">AI EVENT MATCH</span><h1>Recommendations for you</h1><div class="muted">Match scores use your skills, interests, department and verified event data.</div></div></div><div class="grid2">${rec.map(recommendCard).join('')||'<div class="card">No recommendations.</div>'}</div><div class="card" style="margin-top:16px"><h2>COMPESA AI Assistant</h2><p class="muted">Ask about event dates, venues, deadlines or your registration status. This demo assistant is constrained to database-backed information.</p><div class="field"><input id="aiq" placeholder="e.g. What is my approved event venue?"></div><button class="btn primary" onclick="answerAI()">Ask verified assistant</button><div id="aiout" style="margin-top:15px"></div></div>`}
 else if(v==='timeline'){const regs=await api('/registrations/me'),results=await api('/results/me');const items=[...regs.map(r=>({date:r.created_at,title:r.event_name,body:`Registration ${r.status}`,ok:r.status==='APPROVED'})),...results.map(r=>({date:r.date,title:r.event_name,body:`Result: ${r.position}`,ok:true}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));c.innerHTML=`<div class="page-head"><div><span class="pill">STUDENT TIMELINE</span><h1>${esc(state.user.name)}</h1><div class="muted">Your COMPESA activity history</div></div></div><div class="card"><div class="timeline">${items.map(x=>`<div class="timeline-item"><b>${esc(x.title)}</b><div>${esc(x.body)}</div><div class="small muted">${esc(String(x.date)).slice(0,10)}</div></div>`).join('')||'<p class="muted">Your timeline will appear here after activity.</p>'}</div></div>`}
else if(v==='preferences'){const p=await api('/profile');c.innerHTML=`<div class="page-head"><div><span class="pill">SMART NOTIFICATIONS</span><h1>Notification Preferences</h1><div class="muted">Control what event categories and channels you want to receive.</div></div></div><div class="grid2"><div class="card"><h2>Event categories</h2><label class="notice"><input type="checkbox" checked> New Coding Events</label><br><label class="notice"><input type="checkbox" checked> Hackathons</label><br><label class="notice"><input type="checkbox" checked> Workshops</label><br><label class="notice"><input type="checkbox"> Gaming Events</label></div><div class="card"><h2>Channels</h2><label class="notice"><input type="checkbox" checked> Portal notifications</label><br><label class="notice"><input type="checkbox" checked> Gmail</label><br><label class="notice"><input type="checkbox"> SMS</label><p class="small muted">Gmail delivery uses your notification email: ${esc(p.notification_email||p.email)}</p><button class="btn primary" onclick="toast('Notification preferences saved for this demo session.')">Save preferences</button></div></div>`}
else if(v==='profile'){const p=await api('/profile');c.innerHTML=profileForm(p)}
 else if(v==='privacy'){const p=await api('/profile');c.innerHTML=`<div class="page-head"><div><span class="pill">PRIVACY CENTER</span><h1>Control your profile visibility</h1><div class="muted">Other students never receive your registration details or personal email.</div></div></div><div class="card"><h2>Visibility</h2><div class="grid3"><label class="notice"><input type="radio" name="pv" value="public" ${p.privacy==='public'?'checked':''}> Public</label><label class="notice"><input type="radio" name="pv" value="college" ${p.privacy==='college'?'checked':''}> College Only</label><label class="notice"><input type="radio" name="pv" value="private" ${p.privacy==='private'?'checked':''}> Private</label></div><button class="btn primary" style="margin-top:16px" onclick="savePrivacy()">Save privacy settings</button></div>`}
 }catch(e){c.innerHTML=`<div class="card danger-box"><b>Could not load this page.</b><p>${esc(e.message)}</p></div>`}}
function recommendCard(r){return `<div class="match" style="margin:10px 0"><div style="display:flex;justify-content:space-between;gap:15px"><div><b>${esc(r.event.name)}</b><div class="small muted">${esc(r.event.category)} • ${esc(r.event.date)} • ${esc(r.event.venue)}</div></div><strong>${r.match}%</strong></div><div class="bar" style="margin-top:10px"><i style="width:${r.match}%"></i></div><div class="small muted" style="margin-top:8px">Skills ${r.breakdown.skills}% • Interests ${r.breakdown.interests}% • Department ${r.breakdown.department}%</div></div>`}
function eventImage(path,cls='event-image'){return path?`<img class="${cls}" src="${esc(path)}" alt="Event image" loading="lazy">`:''}
function eventCardStudent(e){const live=e.live_status&&e.live_status!=='SCHEDULED';return `<article class="card event-card"><div class="event-cover">${e.banner_path?eventImage(e.banner_path,'event-banner'):''}<span class="pill event-cover-pill">${esc(e.category)}</span>${live?`<span class="status ${e.live_status==='LIVE'?'APPROVED':'PENDING'}" style="margin-left:6px">${e.live_status==='LIVE'?'🔴 LIVE':esc(e.live_status)}</span>`:''}</div><div class="event-body"><h3>${esc(e.name)}</h3><p class="muted">${esc(e.description)}</p><div class="event-meta"><span>📅 ${esc(e.date)} • ${esc(e.start_time)}–${esc(e.end_time)}</span><span>📍 ${esc(e.venue)}</span><span>● ${esc(e.availability||'Open')}</span></div>${live&&e.live_title?`<div class="notice"><b>${esc(e.live_title)}</b>${e.current_round?` • ${esc(e.current_round)}`:''}${e.live_venue?`<br>📍 ${esc(e.live_venue)}`:''}</div>`:''}<div class="actions"><button class="btn ghost" onclick="viewStudentEvent(${e.id})">View Event</button><button class="btn primary" onclick="registerEvent(${e.id})">Individual register</button>${e.team_enabled?`<button class="btn ghost" onclick="teamRegister(${e.id},'${esc(e.name)}')">Team registration</button>`:''}${live?`<button class="btn ghost" onclick="studentLive(${e.id})">Live updates</button>`:''}</div></div></article>`}
async function viewStudentEvent(id){try{const d=await api('/events/'+id);const e=d.event;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="studentEventModal"><div class="modal-card">${e.banner_path?eventImage(e.banner_path,'event-detail-banner'):''}${e.poster_path?`<img class="event-poster" src="${esc(e.poster_path)}" alt="${esc(e.name)} poster">`:''}<span class="pill">${esc(e.category)}</span><h2>${esc(e.name)}</h2><p class="muted">${esc(e.description||'')}</p><div class="grid2"><div class="notice"><b>📅 Date & Time</b><br>${esc(e.date)} • ${esc(e.start_time)}–${esc(e.end_time)}</div><div class="notice"><b>📍 Venue</b><br>${esc(e.venue)}</div><div class="notice"><b>💳 Registration Fee</b><br>₹${Number(e.fee||0).toLocaleString('en-IN')}</div><div class="notice"><b>⏰ Deadline</b><br>${esc(e.deadline||'As announced')}</div></div><h3 style="margin-top:20px">Rules & Information</h3><p class="muted" style="white-space:pre-wrap">${esc(e.rules||'No additional rules published.')}</p><div style="display:flex;gap:10px;margin-top:18px;flex-wrap:wrap"><button class="btn primary" onclick="studentEventModal.remove();registerEvent(${e.id})">Register Now</button><button class="btn ghost" onclick="studentEventModal.remove()">Close</button></div></div></div>`)}catch(e){toast(e.message)}}
async function studentLive(id){try{const x=await api('/events/'+id+'/live');document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="studentLiveModal"><div class="modal-card"><span class="status APPROVED">${esc(x.live_status)}</span><h2>${esc(x.live_title||x.name)}</h2><p class="muted">📍 ${esc(x.live_venue||x.venue)} • ${esc(x.live_date||x.date)} • ${esc(x.live_start_time||x.start_time)}–${esc(x.live_end_time||x.end_time)}</p>${x.current_round?`<div class="notice"><b>Current round:</b> ${esc(x.current_round)}</div>`:''}<h3>Instructions</h3><p>${esc(x.live_instructions||'No special instructions.')}</p>${x.emergency_message?`<div class="danger-box"><b>Important update</b><p>${esc(x.emergency_message)}</p></div>`:''}<button class="btn ghost" onclick="studentLiveModal.remove()">Close</button></div></div>`)}catch(e){toast(e.message)}}
async function registerEvent(id){try{const e=await api('/events/'+id); const fee=Number(e.event.fee||0); document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="payModal"><div class="modal-card"><span class="pill">EVENT REGISTRATION</span><h2>${esc(e.event.name)}</h2><p class="muted">Registration fee: <b>₹${fee.toLocaleString('en-IN')}</b></p>${fee>0?`<div class="field"><label>Payment mode</label><select id="paymentMode" onchange="togglePaymentQR()"><option value="OFFLINE">Pay at desk / offline</option><option value="ONLINE">Online payment</option></select></div><div id="paymentQRBox" style="display:none;text-align:center;background:#101010;border-radius:18px;padding:16px"><h3 style="color:#fff">Scan to pay online</h3><img src="/static/assets/payment_qr.png" style="width:100%;max-width:390px;border-radius:12px"><p style="color:#fff" class="small">After payment, enter your transaction/reference number below.</p><div class="field"><label style="color:#fff">Payment reference</label><input id="paymentRef" placeholder="UPI transaction / reference ID"></div></div>`:'<div class="success-box">This is a free event. No payment is required.</div>'}<div style="display:flex;gap:10px;margin-top:16px"><button class="btn primary" onclick="confirmEventRegistration(${id})">Continue registration</button><button class="btn ghost" onclick="payModal.remove()">Cancel</button></div></div></div>`);}catch(e){toast(e.message)}}
function togglePaymentQR(){const online=$('#paymentMode')?.value==='ONLINE'; const box=$('#paymentQRBox'); if(box) box.style.display=online?'block':'none';}
async function confirmEventRegistration(id){try{const mode=$('#paymentMode')?.value||'OFFLINE';const ref=$('#paymentRef')?.value||'';if(mode==='ONLINE'&&!ref.trim()){toast('Enter the online payment reference number after payment.');return}const d=await api('/registrations/'+id+'?payment_mode='+encodeURIComponent(mode)+'&payment_reference='+encodeURIComponent(ref),{method:'POST'});$('#payModal')?.remove();toast(`Registration ${d.status}. ${mode==='ONLINE'?'Online payment reference saved. ':''}Admin approval is required before your QR becomes active.`);studentView('registrations')}catch(e){toast(e.message)}}
async function markRead(id){await api('/notifications/'+id+'/read',{method:'PATCH'});studentView('notifications')}
function showQR(id,event,reg){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="qrmodal"><div class="modal-card" style="text-align:center"><span class="pill">SECURE QR PASS</span><h2>${esc(event)}</h2><p class="mono">${esc(reg)}</p><img src="/api/qr/${id}.png?access_token=${encodeURIComponent(state.token)}" style="width:260px;border:10px solid #fff;box-shadow:0 15px 40px #0001"><p class="muted">Show this QR to COMPESA event staff for verification and attendance.</p><button class="btn ghost" onclick="qrmodal.remove()">Close</button></div></div>`)}
function profileForm(p){return `<div class="page-head"><div><span class="pill">PERSONAL PROFILE</span><h1>My Profile</h1><div class="muted">Your branch, division and contact information stay attached to your registrations.</div></div></div><form class="card" id="profileForm"><div class="grid2"><div class="field"><label>Full Name</label><input id="pn" value="${esc(p.name)}"></div><div class="field"><label>PRN / Roll No.</label><input id="pp" value="${esc(p.prn)}"></div><div class="field"><label>Department / Branch</label><input id="pd" value="${esc(p.department)}"></div><div class="field"><label>Year</label><input id="py" value="${esc(p.year)}"></div><div class="field"><label>Division</label><input id="pvdiv" value="${esc(p.division)}"></div><div class="field"><label>Mobile</label><input id="pmo" value="${esc(p.phone||'')}"></div><div class="field"><label>Student Email</label><input value="${esc(p.email)}" disabled></div><div class="field"><label>Gmail / Notification Email</label><input id="pg" type="email" value="${esc(p.notification_email||p.email)}"></div><div class="field"><label>Skills</label><input id="ps" value="${esc(p.skills||'')}"></div><div class="field"><label>Interests</label><input id="pi" value="${esc(p.interests||'')}"></div></div><button class="btn primary">Save profile</button></form>`}
async function savePrivacy(){const p=await api('/profile');p.privacy=$('input[name="pv"]:checked').value;await api('/profile',{method:'PUT',body:JSON.stringify(p)});toast('Privacy settings saved')}
async function answerAI(){const q=$('#aiq').value.toLowerCase();const regs=await api('/registrations/me'),events=await api('/events');let ans='I can answer from verified COMPESA data. ';if(q.includes('venue')){const r=regs.find(x=>x.status==='APPROVED');ans+=r?`Your approved event <b>${esc(r.event_name)}</b> is at <b>${esc(r.venue)}</b>.`:'You currently have no approved registration.'}else if(q.includes('deadline')){ans=events.length?events.map(e=>`<b>${esc(e.name)}</b>: ${esc(e.deadline||'Not specified')}`).join('<br>'):'No events found.'}else if(q.includes('upcoming')||q.includes('coding')){const rec=await api('/ai/recommendations');const rs=rec.slice(0,5);ans=rs.length?rs.map(e=>`<b>${esc(e.event.name)}</b> — ${e.event.date}, ${esc(e.event.venue)} — ${e.match}% match`).join('<br>'):'No personalized matching events found.'}else{ans='Try asking: “What is my approved event venue?”, “What are the coding events?”, or “What is the registration deadline?”'}$('#aiout').innerHTML=`<div class="notice">${ans}</div>`}
async function saveProfile(){const body={name:pn.value,prn:pp.value,department:pd.value,year:py.value,division:pvdiv.value,phone:pmo.value,notification_email:pg.value,skills:ps.value,interests:pi.value,privacy:state.user.privacy};await api('/profile',{method:'PUT',body:JSON.stringify(body)});state.user=await api('/auth/me');toast('Profile updated');studentView('profile')}
document.addEventListener('submit',e=>{if(e.target.id==='profileForm'){e.preventDefault();saveProfile()}});

async function downloadCSV(url,filename){try{if(!state.token){toast('Please login again');return}const res=await fetch(url,{headers:{Authorization:'Bearer '+state.token}});if(!res.ok){const d=await res.json().catch(()=>({}));throw new Error(d.detail||'CSV download failed')}const blob=await res.blob();const objectUrl=URL.createObjectURL(blob);const a=document.createElement('a');a.href=objectUrl;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000);toast('CSV downloaded successfully');}catch(e){toast(e.message||'CSV download failed')}}

async function adminView(v){navActive(v);const c=$('#content');try{
 if(v==='dashboard'){const d=await api('/dashboard');c.innerHTML=`<div class="page-head"><div><span class="pill">ADMIN COMMAND CENTER</span><h1>Operations Overview</h1><div class="muted">Real-time control over students, events, approvals and communications.</div></div><div><button class="btn primary" onclick="adminView('registrations')">Review pending approvals</button></div></div><div class="grid">${[['Students',d.students,'◉'],['Events',d.events,'◇'],['Registrations',d.registrations,'✓'],['Pending Approvals',d.pending,'!'],['Upcoming Events',d.upcoming,'📅'],['Attendance Records',d.attendance,'▣'],['Certificates',d.certificates,'▤'],['Approved Revenue','₹'+Number(d.revenue||0).toLocaleString('en-IN'),'₹']].map(x=>`<div class="card stat-card"><span class="stat-icon">${x[2]}</span><div class="stat-label">${x[0]}</div><div class="stat-num">${x[1]}</div></div>`).join('')}</div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Department participation</h2>${d.departments.map(x=>`<div style="margin:12px 0"><div style="display:flex;justify-content:space-between"><b>${esc(x.department)}</b><span>${x.count}</span></div><div class="bar"><i style="width:${Math.min(100,x.count/Math.max(1,d.registrations)*100)}%"></i></div></div>`).join('')||'<p class="muted">No registration data.</p>'}</div><div class="card"><h2>Popular categories</h2>${d.categories.map(x=>`<div style="display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #eef2f6"><span>${esc(x.category)}</span><b>${x.count}</b></div>`).join('')||'<p class="muted">No category data.</p>'}</div></div>`}
 else if(v==='registrations'){const rows=await api('/registrations');c.innerHTML=`<div class="page-head"><div><span class="pill">APPROVAL WORKFLOW</span><h1>Registration Approvals</h1><div class="muted">Student branch, year, division, email and event details are visible to authorized admins.</div></div></div><div class="search-row"><input id="rq" placeholder="Search name / PRN" oninput="filterRegs()"><select id="rsx" onchange="filterRegs()"><option value="">All status</option><option>PENDING</option><option>APPROVED</option><option>REJECTED</option><option>WAITLISTED</option></select><select id="rdx" onchange="filterRegs()"><option value="">All branches</option>${[...new Set(rows.map(x=>x.department))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="card table-wrap"><table class="table"><thead><tr><th>Student</th><th>Academic</th><th>Event</th><th>Contact</th><th>Status</th><th>Action</th></tr></thead><tbody id="regbody">${rows.map(regRow).join('')}</tbody></table></div>`;window._regs=rows}
 else if(v==='students'){const rows=await api('/students');c.innerHTML=`<div class="page-head"><div><span class="pill">STUDENT DIRECTORY</span><h1>Students</h1><div class="muted">Admins can see academic identity and notification email; students cannot see this directory.</div></div></div><div class="search-row"><input id="stq" placeholder="Search student / PRN" oninput="filterStudents()"><select id="std"><option value="">All branches</option>${[...new Set(rows.map(x=>x.department))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="card table-wrap"><table class="table"><thead><tr><th>Name</th><th>PRN</th><th>Branch</th><th>Year / Div</th><th>Gmail</th><th>Points</th></tr></thead><tbody id="stbody">${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="mono">${esc(x.prn)}</td><td>${esc(x.department)}</td><td>${esc(x.year)} / ${esc(x.division)}</td><td>${esc(x.notification_email||x.email)}</td><td><b>${x.points}</b> ⭐</td></tr>`).join('')}</tbody></table></div>`;window._students=rows}
 else if(v==='events'){const rows=await api('/events');c.innerHTML=`<div class="page-head"><div><span class="pill">EVENT ENGINE</span><h1>Event Management</h1><div class="muted">Create and edit events, schedules, fees and venues with conflict prevention.</div></div></div><div class="grid2"><div class="card"><h2>Create Event</h2><form id="eventForm"><div class="field"><label>Event Name</label><input id="en" required></div><div class="grid2"><div class="field"><label>Category</label><select id="ec"><option>Coding Competition</option><option>Hackathon</option><option>Workshop</option><option>Seminar</option><option>Quiz</option><option>Gaming</option><option>Project Exhibition</option></select></div><div class="field"><label>Date</label><input id="ed" type="date" required></div><div class="field"><label>Start</label><input id="es" type="time" value="10:00"></div><div class="field"><label>End</label><input id="ee" type="time" value="16:00"></div><div class="field"><label>Venue</label><input id="ev" required></div><div class="field"><label>Max Participants</label><input id="em" type="number" value="100"></div><div class="field"><label>Team Size</label><input id="et" type="number" value="1"></div><div class="field"><label>Fee ₹</label><input id="ef" type="number" value="0"></div></div><div class="field"><label>Registration Deadline</label><input id="edl" type="datetime-local"></div><div class="field"><label>Description</label><textarea id="edesc"></textarea></div><div class="field"><label>Rules</label><textarea id="erules">Bring college ID. Follow COMPESA event rules.</textarea></div><button class="btn primary">Create Event</button></form></div><div class="card"><h2>Event templates</h2>${['Coding Competition','Workshop','Hackathon','Quiz','Seminar','Gaming','Project Exhibition'].map(x=>`<div class="notice" style="margin:9px 0;cursor:pointer" onclick="en.value='${x}';ec.value='${x}'">${x}</div>`).join('')}</div></div><div class="card" style="margin-top:16px"><h2>Current events</h2><div class="grid2">${rows.map(e=>`<div class="notice"><b>${esc(e.name)}</b><div class="small muted">${esc(e.category)} • ${e.date} • ${esc(e.start_time)}–${esc(e.end_time)} • 📍 ${esc(e.venue)}</div><div style="margin-top:8px"><span class="pill">Fee: ₹${Number(e.fee||0).toLocaleString('en-IN')}</span></div><div style="margin-top:10px"><button class="btn ghost sm" onclick="editEvent(${e.id})">Edit event</button> <button class="btn primary sm" onclick="adminView('live');setTimeout(()=>loadLiveEditor(${e.id}),100)">Live mode</button> <button class="btn danger sm" onclick="deleteEvent(${e.id},'${esc(e.name)}')">Delete event</button></div></div>`).join('')}</div></div>`;$('#eventForm').onsubmit=async e=>{e.preventDefault();try{await api('/events',{method:'POST',body:JSON.stringify({name:en.value,description:edesc.value,category:ec.value,date:ed.value,start_time:es.value,end_time:ee.value,venue:ev.value,max_participants:+em.value,team_size:+et.value,fee:+ef.value,deadline:edl.value,rules:erules.value,coordinators:state.user.name})});toast('Event created');adminView('events')}catch(err){toast(err.message)}}}
 else if(v==='analytics'){const a=await api('/analytics'),d=await api('/dashboard');c.innerHTML=`<div class="page-head"><div><span class="pill">DATA INTELLIGENCE</span><h1>Advanced Analytics</h1><div class="muted">Participation, attendance, categories and active-student signals.</div></div></div><div class="grid"><div class="card stat-card"><div class="stat-label">Attendance %</div><div class="stat-num">${a.attendance_percent||0}%</div></div><div class="card stat-card"><div class="stat-label">Average Rating</div><div class="stat-num">${a.rating.avg||0}/5</div></div><div class="card stat-card"><div class="stat-label">Feedback Responses</div><div class="stat-num">${a.rating.responses||0}</div></div><div class="card stat-card"><div class="stat-label">Active Students</div><div class="stat-num">${a.active_students.length}</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Registration trend</h2><div class="chart">${(d.months.length?d.months:[{month:'Now',count:d.registrations}]).map(x=>`<div class="col"><div class="barcol" style="height:${Math.max(8,Math.min(150,x.count*8))}px"></div><b>${x.count}</b><span class="lbl">${esc(x.month)}</span></div>`).join('')}</div></div><div class="card"><h2>Registration type</h2><div class="donut-wrap"><div class="donut"></div><div>${a.registration_types.map(x=>`<p><b>${esc(x.type)}</b> — ${x.count}</p>`).join('')}</div></div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Most active students</h2><table class="table"><tr><th>Student</th><th>Registrations</th></tr>${a.active_students.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.c}</td></tr>`).join('')}</table></div><div class="card"><h2>Popular categories</h2>${a.categories.map(x=>`<div style="display:flex;justify-content:space-between;padding:12px;border-bottom:1px solid #edf1f5"><span>${esc(x.category)}</span><b>${x.count}</b></div>`).join('')}</div></div>`}
 else if(v==='communication'){const s=await api('/communication/status');c.innerHTML=`<div class="page-head"><div><span class="pill">AUTOMATED COMMUNICATION</span><h1>Communication Center</h1><div class="muted">Approval emails, delivery status, retries and notification audit trail.</div></div><span class="status ${s.configured?'APPROVED':'PENDING'}">SMTP ${s.configured?'CONFIGURED':'NOT CONFIGURED'}</span></div><div class="grid3"><div class="card stat-card"><div class="stat-label">Sent</div><div class="stat-num">${(s.stats.find(x=>x.status==='SENT')||{}).count||0}</div></div><div class="card stat-card"><div class="stat-label">Failed</div><div class="stat-num">${(s.stats.find(x=>x.status==='FAILED')||{}).count||0}</div></div><div class="card stat-card"><div class="stat-label">Not configured</div><div class="stat-num">${(s.stats.find(x=>x.status==='NOT_CONFIGURED')||{}).count||0}</div></div></div><div class="grid2" style="margin-top:16px"><div class="card"><h2>Send configuration test</h2><p class="muted">This sends a real test email when Gmail SMTP is configured in .env.</p><div class="field"><input id="testmail" type="email" placeholder="recipient@gmail.com"></div><button class="btn primary" onclick="testEmail()">Send test email</button></div><div class="card"><h2>Recent delivery log</h2><div class="table-wrap"><table class="table"><tr><th>Student</th><th>To</th><th>Status</th><th>Time</th></tr>${s.recent.map(x=>`<tr><td>${esc(x.student_name)}</td><td>${esc(x.to_email)}</td><td>${esc(x.status)}</td><td>${esc(x.created_at).slice(0,16).replace('T',' ')}</td></tr>`).join('')}</table></div></div></div>`}
 else if(v==='qr'){c.innerHTML=`<div class="page-head"><div><span class="pill">QR ATTENDANCE</span><h1>Scanner & Verification</h1><div class="muted">Use the laptop/mobile camera to scan secure COMPESA registration QR codes.</div></div></div><div class="grid2"><div class="card"><h2>Camera scanner</h2><video id="qrvideo" playsinline style="width:100%;max-height:380px;background:#06101d;border-radius:16px"></video><div class="actions" style="margin-top:12px"><button class="btn primary" onclick="startCameraScanner()">Start camera</button><button class="btn ghost" onclick="stopCameraScanner()">Stop</button></div><div id="camout" style="margin-top:12px"></div></div><div class="card"><h2>Manual secure token</h2><div class="field"><label>Paste token from QR</label><input id="qrt" placeholder="Secure registration token"></div><button class="btn primary" onclick="scanQR()">Verify & mark attendance</button><div id="qrout" style="margin-top:15px"></div><div class="notice" style="margin-top:15px">The backend validates the token, approval status and duplicate attendance before marking entry.</div></div></div>`}
 else if(v==='certificates'){const certs=await api('/certificates'),events=await api('/events'),students=await api('/students');c.innerHTML=`<div class="page-head"><div><span class="pill">CERTIFICATE CENTER</span><h1>Certificates</h1><div class="muted">Generate, upload, hash and publicly verify certificates.</div></div></div><div class="grid2"><div class="card"><h2>Generate certificate</h2><div class="field"><label>Event</label><select id="ce">${events.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Student</label><select id="cu">${students.map(x=>`<option value="${x.id}">${esc(x.name)} • ${esc(x.prn)}</option>`).join('')}</select></div><button class="btn primary" onclick="generateCert()">Generate signed certificate</button><hr style="border:0;border-top:1px solid #edf1f5;margin:20px 0"><h2>Upload certificate</h2><form id="uploadCert" enctype="multipart/form-data"><div class="field"><label>Event</label><select name="event_id">${events.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Student</label><select name="user_id">${students.map(x=>`<option value="${x.id}">${esc(x.name)} • ${esc(x.prn)}</option>`).join('')}</select></div><div class="field"><label>PDF / JPG / PNG</label><input name="certificate" type="file" accept=".pdf,.png,.jpg,.jpeg" required></div><button class="btn ghost">Upload certificate</button></form></div><div class="card"><h2>Issued certificates</h2><div class="table-wrap"><table class="table"><tr><th>Student</th><th>Event</th><th>ID</th><th>Source</th><th></th></tr>${certs.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.event_name)}</td><td class="mono">${esc(x.cert_id)}</td><td>${esc(x.source||'generated')}</td><td><a class="btn sm ghost" href="/api/certificates/${encodeURIComponent(x.cert_id)}/pdf" target="_blank">Open</a></td></tr>`).join('')}</table></div></div></div>`;$('#uploadCert').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const r=await fetch('/api/certificates/upload',{method:'POST',headers:{Authorization:'Bearer '+state.token},body:fd});const d=await r.json();if(!r.ok)return toast(d.detail||'Upload failed');toast('Certificate uploaded and verification record created');adminView('certificates')}}
 else if(v==='results'){const students=await api('/students'),events=await api('/events');c.innerHTML=`<div class="page-head"><div><span class="pill">RESULT MANAGEMENT</span><h1>Publish Results</h1></div></div><div class="card"><div class="grid2"><div class="field"><label>Event</label><select id="reid">${events.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Student</label><select id="ruid">${students.map(x=>`<option value="${x.id}">${esc(x.name)} • ${esc(x.prn)}</option>`).join('')}</select></div><div class="field"><label>Position</label><select id="rpos"><option>Winner</option><option>1st Runner Up</option><option>2nd Runner Up</option><option>Special Mention</option></select></div><div class="field"><label>Score</label><input id="rscore" type="number" value="100"></div></div><button class="btn primary" onclick="publishResult()">Publish result + notify student</button></div>`}
 else if(v==='venues'){const rows=await api('/venues');c.innerHTML=`<div class="page-head"><div><span class="pill">SMART VENUE SYSTEM</span><h1>Venue Manager</h1><div class="muted">Create, edit, activate/deactivate and locate campus venues.</div></div></div><div class="grid2"><div class="card"><h2>Add / Update Venue</h2><form id="venueForm"><input type="hidden" id="vid"><div class="grid2"><div class="field"><label>Name</label><input id="vn" required></div><div class="field"><label>Building</label><input id="vb"></div><div class="field"><label>Floor</label><input id="vf"></div><div class="field"><label>Room</label><input id="vr"></div><div class="field"><label>Capacity</label><input id="vc" type="number" value="60"></div><div class="field"><label>Facilities</label><input id="vfac" placeholder="Wi-Fi,Projector,AC"></div></div><div class="field"><label>Address</label><input id="vaddr"></div><div class="field"><label>Google Maps link</label><input id="vmap" type="url"></div><div class="grid2"><div class="field"><label>Latitude</label><input id="vlat" type="number" step="any"></div><div class="field"><label>Longitude</label><input id="vlon" type="number" step="any"></div></div><label class="notice"><input id="vavail" type="checkbox" checked> Available for booking</label><div style="margin-top:15px"><button class="btn primary">Save venue</button> <button type="button" class="btn ghost" onclick="resetVenueForm()">Clear</button></div></form></div><div class="card"><h2>Campus venues</h2>${rows.map(x=>`<div class="notice" style="margin:9px 0"><div style="display:flex;justify-content:space-between;gap:10px"><b>${esc(x.name)}</b><span class="status ${x.available?'APPROVED':'PENDING'}">${x.available?'AVAILABLE':'UNAVAILABLE'}</span></div><div class="small muted">${esc(x.building)} • Floor ${esc(x.floor)} • ${esc(x.room)} • Capacity ${x.capacity}</div><div class="small">${esc(x.address||'No address')} ${x.maps_url?`• <a href="${esc(x.maps_url)}" target="_blank">Map</a>`:''}</div><div style="margin-top:8px"><button class="btn ghost sm" onclick='fillVenue(${JSON.stringify(x)})'>Edit</button> <button class="btn danger sm" onclick="deleteVenue(${x.id})">Remove</button></div></div>`).join('')}</div></div>`;$('#venueForm').onsubmit=saveVenue}
 else if(v==='live'){const events=await api('/events');c.innerHTML=`<div class="page-head"><div><span class="status APPROVED">🔴 LIVE MODE</span><h1>Live Event Command Center</h1><div class="muted">Edit live status, title, venue, timing, round, instructions and emergency updates.</div></div></div><div class="card"><div class="field"><label>Select event</label><select id="liveEventSelect" onchange="loadLiveEditor(this.value)">${events.map(x=>`<option value="${x.id}">${esc(x.name)} • ${x.date}</option>`).join('')}</select></div><div id="liveEditor"></div></div>`;if(events.length)loadLiveEditor(events[0].id)}
 else if(v==='ai'){c.innerHTML=`<div class="page-head"><div><span class="pill">AI EVENT COPILOT</span><h1>Admin Copilot</h1><div class="muted">AI drafts; an authorized admin must review and publish.</div></div></div><div class="grid2"><div class="card"><h2>Describe your event</h2><div class="field"><textarea id="aiprompt" rows="6" placeholder="Create a Python coding competition for second-year computer students."></textarea></div><button class="btn primary" onclick="draftAI()">Generate structured draft</button></div><div class="card"><h2>Rule Checker</h2><div class="field"><textarea id="rulescheck" rows="6" placeholder="Paste event rules…"></textarea></div><button class="btn ghost" onclick="checkRules()">Check rules</button><div id="ruleout" style="margin-top:12px"></div></div></div><div id="aidraft" style="margin-top:16px"></div>`}
 else if(v==='reports'){c.innerHTML=`<div class="page-head"><div><span class="pill">REPORTS</span><h1>Student & Event Records</h1><div class="muted">Download registration, attendance, participant and student records as CSV. Passwords are never exported.</div></div></div><div class="grid2"><div class="card"><h2>Registered Students</h2><p class="muted">Registration records with student academic details, event and status.</p><button class="btn primary sm" onclick="downloadCSV('/api/reports/registrations.csv','compesa_registrations.csv')">Download Registered CSV</button></div><div class="card"><h2>Attended Students</h2><p class="muted">Students whose QR attendance was successfully recorded.</p><button class="btn primary sm" onclick="downloadCSV('/api/reports/attendance.csv','compesa_attended_students.csv')">Download Attended CSV</button></div><div class="card"><h2>Event Participants</h2><p class="muted">Registered + attendance status + payment status in one event report.</p><button class="btn primary sm" onclick="downloadCSV('/api/reports/participants.csv','compesa_event_participants.csv')">Download Participants CSV</button></div><div class="card"><h2>All Student Records</h2><p class="muted">Admin-only student directory export including branch/year/division/contact.</p><button class="btn primary sm" onclick="downloadCSV('/api/reports/students.csv','compesa_all_students.csv')">Download Students CSV</button></div></div>`}
 else if(v==='advanced'){const d=await api('/dashboard'),a=await api('/analytics');c.innerHTML=`<div class="page-head"><div><span class="pill">INNOVATION ENGINE</span><h1>Advanced COMPESA Engine</h1><div class="muted">Operational modules for waitlists, competitions, integrity, venues, privacy, engagement and event intelligence.</div></div></div><div class="grid3"><div class="card"><h3>🔥 Smart Waitlist</h3><p class="muted">Automatic WAITLISTED status is created when event capacity is reached. Cancellation can promote the next queue entry.</p><button class="btn ghost sm" onclick="adminView('registrations')">Open queue</button></div><div class="card"><h3>🏁 Multi-Round Engine</h3><p class="muted">Rounds, scores and qualification are supported through the competition workflow.</p><button class="btn ghost sm" onclick="adminView('live')">Open live mode</button></div><div class="card"><h3>💻 Coding Contest</h3><p class="muted">Problems and safe demo submissions are available without arbitrary server-side code execution.</p><button class="btn ghost sm" onclick="toast('Open a coding event and use the problem/submission API.')">Practice</button></div><div class="card"><h3>🕵 Fraud Monitor</h3><p class="muted">Audit logs and registration patterns can be reviewed before any administrative decision.</p><button class="btn ghost sm" onclick="adminView('audit')">Review logs</button></div><div class="card"><h3>📅 Academic Conflict</h3><p class="muted">Venue conflict checks are enforced at event creation; academic calendar records can be connected to the same validation layer.</p><button class="btn ghost sm" onclick="adminView('events')">Create / validate</button></div><div class="card"><h3>📍 Smart Venue</h3><p class="muted">Capacity + facilities are stored and overlapping venue slots are rejected.</p><button class="btn ghost sm" onclick="adminView('venues')">Venue manager</button></div><div class="card"><h3>📈 Engagement Score</h3><p class="muted">Built from participation, attendance, achievements and volunteering signals.</p><div class="stat-num">${Math.min(100,Math.round((a.attendance_percent||0)*.6+20))}/100</div></div><div class="card"><h3>🎯 Event Success Score</h3><p class="muted">Transparent operational indicators instead of arbitrary AI scoring.</p><div class="stat-num">${Math.min(100,Math.round((a.attendance_percent||0)*.5+(a.rating.avg||0)*10))}%</div></div><div class="card"><h3>🔐 Certificate Integrity</h3><p class="muted">Every certificate record stores a deterministic SHA-256 integrity hash and public verification ID.</p><button class="btn ghost sm" onclick="adminView('certificates')">Certificate center</button></div><div class="card"><h3>🗺 Interactive Event Map</h3><p class="muted">Venue building/floor/room data is ready for a campus map layer.</p><button class="btn ghost sm" onclick="adminView('venues')">View venues</button></div><div class="card"><h3>🧠 Event Knowledge Base</h3><p class="muted">Events carry description, rules, schedule, venue and notifications as one information hub.</p><button class="btn ghost sm" onclick="adminView('events')">Open events</button></div><div class="card"><h3>🌐 Public API</h3><p class="muted">Public event/results and certificate verification endpoints are available for future mobile/college integrations.</p><span class="pill">API-FIRST</span></div></div>`}
else if(v==='volunteers'){const rows=await api('/volunteers'),events=await api('/events');c.innerHTML=`<div class="page-head"><div><span class="pill">VOLUNTEER MANAGEMENT</span><h1>Volunteer Operations</h1><div class="muted">Add, edit, remove volunteers and assign event positions/shifts.</div></div></div><div class="grid2"><div class="card"><h2>Add / Edit Volunteer</h2><form id="volForm"><input type="hidden" id="volid"><div class="grid2"><div class="field"><label>Name *</label><input id="voln" required></div><div class="field"><label>PRN / Employee ID</label><input id="volprn"></div><div class="field"><label>Email</label><input id="volemail" type="email"></div><div class="field"><label>Contact</label><input id="volphone"></div><div class="field"><label>Department</label><input id="voldept"></div><div class="field"><label>Event</label><select id="volevent"><option value="">Unassigned</option>${events.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Position</label><select id="volpos">${['President','Vice President','Secretary','Treasurer','Coordinator'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Shift</label><input id="volshift" placeholder="10:00–13:00"></div><div class="field"><label>Status</label><select id="volstatus"><option>ACTIVE</option><option>INACTIVE</option></select></div></div><div class="field"><label>Responsibilities</label><textarea id="volresp"></textarea></div><div class="field"><label>Notes</label><textarea id="volnotes"></textarea></div><button class="btn primary">Save volunteer</button> <button type="button" class="btn ghost" onclick="resetVolunteerForm()">Clear</button></form></div><div class="card"><h2>Assigned volunteers</h2><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Event</th><th>Position</th><th>Contact</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="small muted">${esc(x.employee_prn||'')}</div></td><td>${esc(x.event_name||'Unassigned')}</td><td>${esc(x.position)}</td><td>${esc(x.phone||x.email||'')}</td><td>${esc(x.status)}</td><td><button class="btn ghost sm" onclick='fillVolunteer(${JSON.stringify(x)})'>Edit</button> <button class="btn danger sm" onclick="deleteVolunteer(${x.id})">Remove</button></td></tr>`).join('')}</tbody></table></div></div></div>`;$('#volForm').onsubmit=saveVolunteer}
else if(v==='payments'){const rows=await api('/events');const paid=rows.filter(x=>Number(x.fee)>0);c.innerHTML=`<div class="page-head"><div><span class="pill">PAYMENT MANAGEMENT</span><h1>Event Revenue</h1><div class="muted">View and edit the current registration fee for every event.</div></div></div><div class="grid3"><div class="card stat-card"><div class="stat-label">Paid Events</div><div class="stat-num">${paid.length}</div></div><div class="card stat-card"><div class="stat-label">Current Event Fees</div><div class="stat-num">₹${paid.reduce((a,x)=>a+Number(x.fee||0),0).toLocaleString('en-IN')}</div></div><div class="card stat-card"><div class="stat-label">Payment Flow</div><div class="stat-num">Ready</div></div></div><div class="card" style="margin-top:16px"><h2>Current event fees</h2><div class="table-wrap"><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Venue</th><th>Current Fee</th><th>Change Fee</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="small muted">${esc(x.category)}</div></td><td>${esc(x.date)}</td><td>${esc(x.venue)}</td><td><b>₹${Number(x.fee||0).toLocaleString('en-IN')}</b></td><td><div style="display:flex;gap:8px;align-items:center"><input id="fee_${x.id}" type="number" min="0" step="1" value="${Number(x.fee||0)}" style="max-width:130px"><button class="btn primary sm" onclick="updateEventFee(${x.id})">Save Fee</button></div></td></tr>`).join('')}</tbody></table></div></div><div class="card" style="margin-top:16px"><h2>Payment workflow</h2><div class="timeline"><div class="timeline-item">Registration fee</div><div class="timeline-item">Payment gateway confirmation</div><div class="timeline-item">Payment Successful → Registration Confirmed</div><div class="timeline-item">Failed payment → retry / admin review</div><div class="timeline-item">Refund status</div></div></div>`}
else if(v==='audit'){const rows=await api('/audit');c.innerHTML=`<div class="page-head"><div><span class="pill">SECURITY</span><h1>Audit Logs</h1><div class="muted">Who changed what and when.</div></div></div><div class="card table-wrap"><table class="table"><tr><th>Time</th><th>Admin</th><th>Action</th><th>Target</th><th>Detail</th></tr>${rows.map(x=>`<tr><td>${esc(x.created_at).slice(0,19).replace('T',' ')}</td><td>${esc(x.name)}</td><td>${esc(x.action)}</td><td>${esc(x.target)}</td><td>${esc(x.detail)}</td></tr>`).join('')}</table></div>`}
 else if(v==='database'){c.innerHTML=`<div class="page-head"><div><span class="pill">DATA SAFETY</span><h1>Database Backup &amp; Restore</h1><div class="muted">Free hosting plans (like Render's free tier) can wipe app storage after a restart or redeploy. Download a backup regularly and keep the file somewhere safe — you can restore it in one click below if the live data ever resets.</div></div></div><div class="card"><h2>⬇ Download backup</h2><p class="muted">Saves everything — students, events, registrations, certificates, results — as one file to your computer.</p><button class="btn primary" onclick="downloadBackup()">Download backup now</button></div><div class="card"><h2>⬆ Restore from backup</h2><p class="muted">Upload a previously downloaded backup file to replace the current data. The live database is safety-copied automatically right before this runs, so a restore can be undone.</p><form id="restoreForm"><input type="file" name="file" accept=".db" required><button class="btn ghost" style="margin-top:10px">Restore from file</button></form></div>`;$('#restoreForm').onsubmit=async e=>{e.preventDefault();if(!confirm('This replaces ALL current data with the uploaded backup. Continue?'))return;const fd=new FormData(e.target);try{const r=await fetch('/api/admin/restore',{method:'POST',headers:{Authorization:'Bearer '+state.token},body:fd});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Restore failed');toast('Database restored successfully');adminView('dashboard')}catch(err){toast(err.message)}}}
 }catch(e){c.innerHTML=`<div class="card danger-box"><b>Could not load this page.</b><p>${esc(e.message)}</p></div>`}}
async function downloadBackup(){try{const r=await fetch('/api/admin/backup',{headers:{Authorization:'Bearer '+state.token}});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.detail||'Backup failed')}const blob=await r.blob();const cd=r.headers.get('Content-Disposition')||'';const m=cd.match(/filename="?([^";]+)"?/);const name=m?m[1]:'compesa_backup.db';const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Backup downloaded')}catch(e){toast(e.message)}}
