let qrStream=null,qrTimer=null,qrCanvas=null,qrBusy=false;
async function submitCameraFrame(){
 try{
  if(qrBusy||!qrStream)return;
  const video=$('#qrvideo');
  if(!video||video.readyState<2)return;
  qrBusy=true;
  if(!qrCanvas)qrCanvas=document.createElement('canvas');
  const maxW=720, scale=Math.min(1,maxW/video.videoWidth||1);
  qrCanvas.width=Math.max(1,Math.round(video.videoWidth*scale));
  qrCanvas.height=Math.max(1,Math.round(video.videoHeight*scale));
  const ctx=qrCanvas.getContext('2d',{willReadFrequently:true});
  ctx.drawImage(video,0,0,qrCanvas.width,qrCanvas.height);
  const blob=await new Promise(resolve=>qrCanvas.toBlob(resolve,'image/jpeg',0.72));
  if(!blob){qrBusy=false;return}
  const fd=new FormData(); fd.append('image',blob,'camera.jpg');
  const res=await fetch('/api/attendance/scan-image',{method:'POST',headers:{Authorization:'Bearer '+state.token},body:fd});
  if(res.ok){const d=await res.json(); $('#qrout').innerHTML=`<div class="success-box">✓ ${esc(d.message)}</div>`; $('#camout').innerHTML='<div class="success-box">QR detected and attendance verified.</div>'; stopCameraScanner(); return;}
  if(res.status!==422 && res.status!==400){const d=await res.json().catch(()=>({detail:'Scan failed'})); $('#camout').innerHTML=`<div class="danger-box">${esc(d.detail||'Scan failed')}</div>`;}
 }catch(e){}
 finally{qrBusy=false;}
}
async function startCameraScanner(){
 try{
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){toast('Camera access requires HTTPS (or localhost) and a browser that supports camera access.');return}
  stopCameraScanner();
  const video=$('#qrvideo');
  qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});
  video.srcObject=qrStream; await video.play();
  $('#camout').innerHTML='<div class="success-box">Camera active — point it at a COMPESA QR. The portal will decode the QR on the server, so BarcodeDetector is not required.</div>';
  qrTimer=setInterval(submitCameraFrame,900);
 }catch(e){toast('Camera permission denied or unavailable. If hosted, open the HTTPS URL and allow camera access.');}
}
function stopCameraScanner(){if(qrTimer)clearInterval(qrTimer);qrTimer=null;if(qrStream)qrStream.getTracks().forEach(t=>t.stop());qrStream=null;const video=$('#qrvideo');if(video)video.srcObject=null;}
